// QM-Abnahme: je Rolle einloggen, /portal (Kernseite) bei 1440 und 390 px screenshoten.
import { createRequire } from "node:module";
import fs from "node:fs";
import path from "node:path";
const require = createRequire(path.join(process.env.HOME || process.env.USERPROFILE, "claude-browser", "package.json"));
const { chromium } = require("playwright");

const BASIS = "http://localhost:3100";
const PASSWORT = "Demo-2026!";
const ROLLEN = [
  ["flaeche", "flaeche@example.com", "/portal"],
  ["investor", "investor@example.com", "/portal"],
  ["anbieter", "anbieter@example.com", "/portal"],
  ["unternehmen", "unternehmen@example.com", "/portal"],
  ["mitglied", "mitglied@example.com", "/portal"],
  ["kommune", "kommune@example.com", "/portal"],
  ["bank", "bank@example.com", "/portal"],
  ["gutachter", "gutachter@example.com", "/portal"],
  ["lieferant", "lieferant@example.com", "/portal"],
  ["admin", "admin@example.com", "/portal/admin"],
];
const OUT = path.join(path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1")), "qm-shots");
fs.mkdirSync(OUT, { recursive: true });

const browser = await chromium.launch();
let fehler = 0;
for (const [name, email, seite] of ROLLEN) {
  for (const breite of [1440, 390]) {
    const ctx = await browser.newContext({ viewport: { width: breite, height: breite === 1440 ? 900 : 844 } });
    const page = await ctx.newPage();
    const konsole = [];
    page.on("pageerror", (e) => konsole.push("pageerror: " + e.message));
    try {
      await page.goto(BASIS + "/login", { waitUntil: "networkidle", timeout: 30000 });
      await page.fill('input[type="email"]', email);
      await page.fill('input[type="password"]', PASSWORT);
      await Promise.all([page.waitForURL("**/portal**", { timeout: 20000 }), page.click('button[type="submit"]')]);
      await page.goto(BASIS + seite, { waitUntil: "networkidle", timeout: 30000 });
      await page.waitForTimeout(500);
      const uberlauf = await page.evaluate(() => document.documentElement.scrollWidth > document.documentElement.clientWidth + 1);
      await page.screenshot({ path: path.join(OUT, `${name}_${breite}.png`), fullPage: false });
      console.log(`OK ${name} @${breite}${uberlauf ? " !HORIZONTALER-UEBERLAUF" : ""}${konsole.length ? " !" + konsole.join("; ") : ""}`);
      if (uberlauf || konsole.length) fehler++;
    } catch (e) {
      fehler++;
      console.log(`FEHLER ${name} @${breite}: ${e.message.split("\n")[0]}`);
      try { await page.screenshot({ path: path.join(OUT, `${name}_${breite}_FEHLER.png`) }); } catch {}
    }
    await ctx.close();
  }
}
await browser.close();
console.log(fehler === 0 ? "ALLE ROLLEN OK" : `FERTIG MIT ${fehler} PROBLEM(EN)`);

